/*
 * A229623  Palindromes m such that m - sum_of_digits(m) is also a palindrome.
 * https://oeis.org/A229623
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the nth palindrome m such that (m - sum_of_digits(m)) is
 *            also a palindrome. For n > 20 the conjectured closed form holds:
 *            a(n) = 10^(n-18) + 1. The first 20 terms are generated by a
 *            straightforward search
 * Range:     u8 n <= 13, u16 n <= 22, u32 n <= 27, u64 n <= 30, u128 n <= 30,
 *            big any n
 * Helpers:   digit_sum, is_palindrome, pow10
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/digit_sum.h"
#include "../utils/is_palindrome.h"
#include "../utils/pow10.h"

seq_t a(idx_t n) {
    /* Handle the trivial 0‑based case (not used in OEIS indexing) */
    if (n == 0) return 0;

    /* Cache for the first 20 terms (indices 1..20) */
    static seq_t cache[21];
    static idx_t computed = 0;   /* number of terms computed so far */

    if (n <= 20) {
        /* Generate terms up to the required index if necessary */
        if (computed < n) {
            seq_t m = 0;          /* candidate palindrome */
            idx_t count = 0;      /* count of valid terms found */

            while (count < n) {
                if (is_palindrome(m, 10)) {
                    seq_t sum  = digit_sum(m);
                    seq_t diff = m - sum;
                    if (is_palindrome(diff, 10))
                        cache[++count] = m;   /* store 1‑based index */
                }
                ++m;
            }
            computed = n;
        }
        return cache[n];
    }

    /* For n > 20 use the conjectured closed form. */
    /* n-18 is non‑negative because n > 20. */
    return pow10(n - 18) + (seq_t)1;
}
